import {
  ElementRef,
  ViewChild,
  AfterViewInit,
  OnDestroy,
  Directive,
} from '@angular/core';
import { hours, minutes } from '../custom-time-input-form/time-consts';

@Directive()
export abstract class CustomTimeBaseComponent
  implements AfterViewInit, OnDestroy
{
  @ViewChild('hourScroll') hourScrollRef!: ElementRef<HTMLDivElement>;
  @ViewChild('minuteScroll') minuteScrollRef!: ElementRef<HTMLDivElement>;
  @ViewChild('periodScroll') periodScrollRef!: ElementRef<HTMLDivElement>;
  @ViewChild('timeInput') timeInputRef!: ElementRef<HTMLInputElement>;

  hours = hours;
  minutes = minutes;
  periods: ('AM' | 'PM')[] = ['AM', 'PM'];

  selectedHour?: number | null;
  selectedMinute?: number | null;
  selectedPeriod: 'AM' | 'PM' = 'AM';

  rangeMin = '';
  rangeMax = '';
  private isDragging = false;
  private startY = 0;
  private startScrollTop = 0;
  protected itemHeight = 44; // Default to 44px based on logs

  ngAfterViewInit() {
    this.updateItemHeight();
    this.scrollToSelectedValues();
    window.addEventListener('resize', this.updateItemHeight);
  }

  ngOnDestroy() {
    // Without this every picker instance keeps a resize handler (and the
    // component it closes over) alive for the lifetime of the page.
    window.removeEventListener('resize', this.updateItemHeight);
  }

  updateItemHeight = () => {
    const containers = [
      this.hourScrollRef,
      this.minuteScrollRef,
      this.periodScrollRef,
    ];

    for (const ref of containers) {
      const item = ref?.nativeElement.querySelector('.time-item');
      if (item) {
        this.itemHeight = item.getBoundingClientRect().height;
        return;
      }
    }
  };

  get filteredHours(): number[] {
    const hoursList =
      this.rangeMin || this.rangeMax ? this.getFilteredHoursList() : this.hours;

    // Move 12 to the top
    const filtered = hoursList.filter((h) => h !== 12);
    if (hoursList.includes(12)) {
      return [12, ...filtered];
    }
    return filtered;
  }

  get filteredPeriods(): ('AM' | 'PM')[] {
    if (!this.rangeMin && !this.rangeMax) {
      return this.periods;
    }

    const validPeriods: ('AM' | 'PM')[] = [];

    if (this.rangeMin) {
      const [minH] = this.rangeMin.split(':').map(Number);
      if (minH < 12 && this.getHoursForPeriod('AM').length > 0) {
        validPeriods.push('AM');
      }
    } else {
      validPeriods.push('AM');
    }

    if (this.rangeMax) {
      const [maxH] = this.rangeMax.split(':').map(Number);
      if (maxH >= 12 && this.getHoursForPeriod('PM').length > 0) {
        validPeriods.push('PM');
      }
    } else {
      validPeriods.push('PM');
    }

    if (
      validPeriods.length === 1 &&
      this.selectedPeriod &&
      validPeriods[0] !== this.selectedPeriod
    ) {
      this.selectedPeriod = validPeriods[0];
    }

    return validPeriods;
  }

  protected goToHour(h: number) {
    this.selectedHour = h;
    this.scrollToSelectedValues();
  }
  protected goToMin(m: number) {
    this.selectedMinute = m;
    this.scrollToSelectedValues();
  }
  protected goToPeriod(p: 'AM' | 'PM') {
    this.selectedPeriod = p;
    this.scrollToSelectedValues();
  }

  protected getFilteredHoursList(): number[] {
    return this.getHoursForPeriod(this.selectedPeriod);
  }

  private getHoursForPeriod(period: 'AM' | 'PM'): number[] {
    return this.hours.filter((h) => {
      let hour24 = h;
      if (period === 'PM' && h !== 12) {
        hour24 = h + 12;
      } else if (period === 'AM' && h === 12) {
        hour24 = 0;
      }

      if (this.rangeMin) {
        const [minH, minM] = this.rangeMin.split(':').map(Number);
        if (hour24 < minH) return false;
        if (hour24 === minH && minM > 55) return false;
      }

      if (this.rangeMax) {
        const [maxH, maxM] = this.rangeMax.split(':').map(Number);
        if (hour24 > maxH) return false;
        if (hour24 === maxH && maxM > 55) return false;
      }

      return true;
    });
  }

  get filteredMinutes(): number[] {
    if (!this.rangeMin && !this.rangeMax) {
      return this.minutes;
    }

    const hour24 = this.to24Hour(
      this.selectedHour || this.filteredHours[0],
      this.filteredPeriods.includes(this.selectedPeriod)
        ? this.selectedPeriod
        : this.filteredPeriods[0],
    );

    return this.minutes.filter((m) => {
      if (this.rangeMin) {
        const [minH, minM] = this.rangeMin.split(':').map(Number);
        if (hour24 === minH && m < minM) return false;
      }

      if (this.rangeMax) {
        const [maxH, maxM] = this.rangeMax.split(':').map(Number);
        if (hour24 === maxH && m > maxM) return false;
      }

      return true;
    });
  }

  protected scrollToSelectedValues() {
    // Wait for next frame to ensure DOM is fully rendered
    requestAnimationFrame(() => {
      if (this.hourScrollRef) {
        const hourIndex = this.filteredHours.indexOf(Number(this.selectedHour));
        if (hourIndex !== -1) {
          this.hourScrollRef.nativeElement.scrollTop =
            hourIndex * this.itemHeight;
        }
      }

      if (this.minuteScrollRef) {
        const minuteIndex = this.filteredMinutes.indexOf(
          Number(this.selectedMinute),
        );
        if (minuteIndex !== -1) {
          this.minuteScrollRef.nativeElement.scrollTop =
            minuteIndex * this.itemHeight;
        }
      }

      if (this.periodScrollRef) {
        const periodIndex = this.filteredPeriods.indexOf(this.selectedPeriod);
        if (periodIndex !== -1) {
          this.periodScrollRef.nativeElement.scrollTop =
            periodIndex * this.itemHeight;
        }
      }
    });
  }

  protected to24Hour(hour: number, period: 'AM' | 'PM'): number {
    if (period === 'PM' && hour !== 12) return hour + 12;
    if (period === 'AM' && hour === 12) return 0;
    return hour;
  }

  protected getCenteredIndex(scrollTop: number): number {
    const centerOffset = scrollTop + this.itemHeight / 2;

    return Math.floor(centerOffset / this.itemHeight);
  }

  getItemOpacity(
    index: number,
    scrollElement: ElementRef<HTMLDivElement> | undefined,
  ): number {
    if (!scrollElement) return 0.3;

    const scrollTop = scrollElement.nativeElement.scrollTop;
    const centerIndex = this.getCenteredIndex(scrollTop);
    const distance = Math.abs(index - centerIndex);

    if (distance === 0) return 1;
    if (distance === 1) return 0.6;
    return 0.3;
  }

  getItemFontWeight(
    index: number,
    scrollElement: ElementRef<HTMLDivElement> | undefined,
  ): string {
    if (!scrollElement) return 'normal';

    const scrollTop = scrollElement.nativeElement.scrollTop;
    const centerIndex = this.getCenteredIndex(scrollTop);

    return index === centerIndex ? 'bold' : 'normal';
  }

  onHourScroll() {
    const scrollTop = this.hourScrollRef.nativeElement.scrollTop;
    const index = this.getCenteredIndex(scrollTop);
    if (this.filteredHours[index] !== undefined) {
      this.selectedHour = this.filteredHours[index];
    }
  }

  onMinuteScroll() {
    const scrollTop = this.minuteScrollRef.nativeElement.scrollTop;
    const index = this.getCenteredIndex(scrollTop);
    if (this.filteredMinutes[index] !== undefined) {
      this.selectedMinute = this.filteredMinutes[index];
    }
  }

  onPeriodScroll() {
    const scrollTop = this.periodScrollRef.nativeElement.scrollTop;
    const index = this.getCenteredIndex(scrollTop);
    if (this.filteredPeriods[index] !== undefined) {
      this.selectedPeriod = this.filteredPeriods[index] as 'AM' | 'PM';
    }
  }

  /**
   * Reads the wheels' scroll positions straight off the DOM. The (scroll)
   * handlers can lag behind momentum/snap scrolling, so this is what makes a
   * confirm pick up the row the user is actually looking at.
   */
  protected syncSelectionFromScroll() {
    if (this.hourScrollRef) {
      const index = this.getCenteredIndex(
        this.hourScrollRef.nativeElement.scrollTop,
      );
      if (this.filteredHours[index] !== undefined) {
        this.selectedHour = this.filteredHours[index];
      }
    }

    if (this.minuteScrollRef) {
      const index = this.getCenteredIndex(
        this.minuteScrollRef.nativeElement.scrollTop,
      );
      if (this.filteredMinutes[index] !== undefined) {
        this.selectedMinute = this.filteredMinutes[index];
      }
    }

    if (this.periodScrollRef) {
      const index = this.getCenteredIndex(
        this.periodScrollRef.nativeElement.scrollTop,
      );
      if (this.filteredPeriods[index] !== undefined) {
        this.selectedPeriod = this.filteredPeriods[index];
      }
    }
  }

  onMouseDown(event: MouseEvent, el: HTMLDivElement) {
    this.isDragging = true;
    this.startY = event.clientY;
    this.startScrollTop = el.scrollTop;

    el.classList.add('dragging');
    event.preventDefault();
  }

  onMouseMove(event: MouseEvent, el: HTMLDivElement) {
    if (!this.isDragging) return;

    const deltaY = event.clientY - this.startY;
    el.scrollTop = this.startScrollTop - deltaY;
  }

  onMouseUp(el: HTMLDivElement) {
    if (!this.isDragging) return;

    this.isDragging = false;
    el.classList.remove('dragging');

    const index = this.getCenteredIndex(el.scrollTop);

    el.scrollTo({
      top: index * this.itemHeight,
      behavior: 'smooth',
    });
  }

  protected setTimeFromString(timeStr: string) {
    const match = timeStr.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
    if (match) {
      this.selectedHour = parseInt(match[1], 10);
      this.selectedMinute = parseInt(match[2], 10);
      this.selectedPeriod = match[3].toUpperCase() as 'AM' | 'PM';
    }
  }
}
