  getCurrentPermissions(): any[] {
    return (
      this.authContextService.userPermissionsAndRoles$()?.permissions ||
      JSON.parse(
        this.storageService.getsessionItem(AuthConstant.USER_PERMISSIONS) ||
          '[]',
      )
    );
  }
  getCurrentRoles(): any[] {
    return JSON.parse(
      this.storageService.getsessionItem(AuthConstant.USER_ROLES) || '[]',
    );
  }
  getCurrentRolesDetails(): any[] {
    // TODO: check usage and remove if not needed
    // return JSON.parse(
    //   this.storageService.getsessionItem(AuthConstant.USER_ROLES_DETAILS) ||
    //     '[]'
    // );
    return [];
  }

  hasAnyCurrentRole(targetRoles: Roles[]): boolean {
    const currentRoles = this.getCurrentRoles();

    if (!Array.isArray(currentRoles) || currentRoles.length === 0) {
      return false;
    }

    return currentRoles.some((role) => targetRoles.includes(role as Roles));
  }

  // PERMISSION MANAGEMENT
  hasCategory(route: ActivatedRouteSnapshot): boolean {
    // console.log('route: ', route);
    // const user = this.getCurrentUser();
    const requiredPermissions = route.data['permissions'] || [];
    const listOfPermissions = this.getCurrentPermissions() || [];

    if (listOfPermissions && listOfPermissions.length > 0) {
      const permissionSet = new Set(listOfPermissions);
      const hasPermission = requiredPermissions.some((permission: string) =>
        permissionSet.has(permission),
      );
      return hasPermission;
    }
    if (requiredPermissions.includes(PERMISSIONS.all) && this.isLoggedIn()) {
      return true;
    }
    return false;
  }

  hasRoles(route: ActivatedRouteSnapshot): boolean {
    // const user = this.getCurrentUser();
    const requiredRoles = route.data['roles'] || [];
    const listOfRoles = this.getCurrentRoles() || [];

    if (listOfRoles && listOfRoles.length > 0) {
      const rolesSet = new Set(listOfRoles);
      const hasRole = requiredRoles.some((role: string) => rolesSet.has(role));
      return hasRole;
    }
    return false;
  }

  canDoAction(action: string[]): boolean {
    // const user = this.getCurrentUser();
    const requiredAction = action;
    // TODO: change to getCurrentPermissions when backend fixed
    // const permissionsList = this.getCurrentPermissions() || [];
    const rolesList = this.getCurrentRoles() || [];
    // console.log('list of roles', permissionsList);
    if (rolesList && rolesList.length > 0) {
      const rolesSet = new Set(rolesList);
      return requiredAction.some((action: string) => rolesSet.has(action));
    }
    return false;
  }

