import {
  Component,
  ElementRef,
  EventEmitter,
  inject,
  input,
  Input,
  OnInit,
  Output,
  signal,
  TemplateRef,
  ViewChild,
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { ReactiveFormsModule } from '@angular/forms';
import { debounceTime, distinctUntilChanged, Subject } from 'rxjs';
import { CustomAppErrorComponent } from '../../custom-app-error/custom-app-error.component';
import { IDropdownOption } from '../../../interfaces';
import { NgStyle, NgTemplateOutlet } from '@angular/common';
import { CustomInputBase } from '../custom-input-base';
import {
  ClickOutsideDirective,
  dropdownAnimation,
  DropdownsAnimationDirective,
} from '../../../directives';
import { LocalizePipe } from '../../../pipes';
import { LoadingService, TranslationService } from '../../../services';
import { TranslateModule } from '@ngx-translate/core';
import {
  trigger,
  state,
  style,
  transition,
  animate,
} from '@angular/animations';

interface IPageSearch {
  nameEn: string;
  nameAr: string;
  size: number;
  page: number;
}

const dropdownAnimationLocal = trigger('dropdown', [
  transition(':enter', [
    style({ height: '0', opacity: 0, overflow: 'hidden' }),
    animate('250ms ease-out', style({ height: '*', opacity: 1 })),
  ]),
  transition(':leave', [
    style({ height: '*', opacity: 1, overflow: 'hidden' }),
    animate('200ms ease-in', style({ height: '0', opacity: 0 })),
  ]),
  transition('* => *', [animate('200ms ease-in-out')]),
]);

@Component({
  selector: 'custom-input-search-expanded-form',
  standalone: true,
  imports: [
    NgStyle,
    ReactiveFormsModule,
    CustomAppErrorComponent,
    ClickOutsideDirective,
    LocalizePipe,
    TranslateModule,
    NgTemplateOutlet,
    DropdownsAnimationDirective,
  ],
  templateUrl: './custom-input-search-form-expanded.component.html',
  styleUrls: ['./custom-input-search-form-expanded.component.css'],
  animations: [dropdownAnimationLocal],
})
export class CustomInputSearchFormExpandedComponent<
  T extends IDropdownOption = IDropdownOption,
>
  extends CustomInputBase
  implements OnInit
{
  @Input() dropdownTemplate!: TemplateRef<{ $implicit: any }>;
  @Output() closingDropdown: EventEmitter<void> = new EventEmitter<void>();
  @ViewChild('inputElement') inputElement?: ElementRef<HTMLInputElement>;
  @ViewChild('dropdownOptions')
  dropdownOptionsElement?: ElementRef<HTMLDivElement>;
  options = input<T[]>([]);
  totalSearchOptions = input<number>(0);
  pageSearch = signal<IPageSearch>({
    nameAr: '',
    nameEn: '',
    size: 10,
    page: 1,
  });

  // @Input()
  openDropdownInput = input<boolean>(false);
  // ) {
  //   if (value) {
  //     console.log('BB', value);
  //     this.openDropdown();
  //   }
  // }

  @Output() optionSelected: EventEmitter<T> = new EventEmitter<T>();
  @Output() viewMoreClicked: EventEmitter<IPageSearch> =
    new EventEmitter<IPageSearch>();

  searching = signal<boolean>(false);
  selectedOption = signal<T | null>(null);

  private inputSubject = new Subject<string>();

  translationService = inject(TranslationService);
  loadingService = inject(LoadingService);

  // Generate unique ID for this component instance
  private uniqueId = `${Math.random().toString(36).substring(2, 11)}`;

  constructor() {
    super();
    this.inputSubject
      .pipe(debounceTime(300), distinctUntilChanged(), takeUntilDestroyed())
      .subscribe((val) => {
        this.pageSearch.set({
          ...this.pageSearch(),
          page: 1,
          nameAr:
            this.translationService.currentLang() === 'ar'
              ? this.parentForm.get(this.controlName)?.value || ''
              : '',

          nameEn:
            this.translationService.currentLang() === 'en'
              ? this.parentForm.get(this.controlName)?.value || ''
              : '',
        });
        this.viewMoreClicked.emit(this.pageSearch());
      });
  }

  override ngOnInit(): void {
    super.ngOnInit();
  }

  get inputId(): string {
    return this.uniqueId;
  }

  onKeyDown(event: KeyboardEvent): void {
    if (event.key === 'Escape' && this.searching()) {
      this.closeDropdown();
      event.preventDefault();
    } else if (event.key === 'Enter' && this.searching()) {
      const filtered = this.filteredOptions;
      if (filtered.length > 0) {
        this.selectOption(filtered[0]);
        event.preventDefault();
      }
    }
  }

  onInput(): void {
    const value = this.parentForm.get(this.controlName)?.value || '';

    // Emit value to debounced subject
    this.inputSubject.next(value);

    // Auto-open dropdown when user starts typing
    if (!this.disabled && !this.searching()) {
      this.openDropdown();
    }
  }

  onFocus(): void {
    if (!this.disabled) {
      this.openDropdown();
      this.onInput();
    }
  }

  closeDropdown(): void {
    this.searching.set(false);
    this.closingDropdown.emit();
  }

  openDropdown(): void {
    this.searching.set(true);
    console.log('searching: ', this.searching());
    console.log('Dropdown opened');
  }

  get clickOutsideElements(): HTMLElement[] {
    const elements: HTMLElement[] = [];
    if (this.dropdownOptionsElement?.nativeElement) {
      elements.push(this.dropdownOptionsElement.nativeElement);
    }
    if (this.inputElement?.nativeElement) {
      elements.push(this.inputElement.nativeElement);
    }
    return elements;
  }

  get filteredOptions(): T[] {
    const options = this.options();
    if (!options || options.length === 0) {
      return [];
    }

    const inputValue = this.parentForm.get(this.controlName)?.value;
    const searchTerm = (inputValue?.toString() || '').toLowerCase().trim();

    // If no search term, return all options
    if (!searchTerm) {
      return options;
    }

    const currentLang = this.translationService.currentLang();

    return options.filter((option) => {
      if (!option) {
        return false;
      }

      const optionName = currentLang === 'ar' ? option.nameAr : option.nameEn;

      // Handle null/undefined option names
      if (!optionName) {
        return false;
      }

      return optionName.toLowerCase().includes(searchTerm);
    });
  }

  selectOption(option: T): void {
    if (!option) {
      return;
    }

    const currentLang = this.translationService.currentLang();
    const optionName = currentLang === 'ar' ? option.nameAr : option.nameEn;

    // Handle null/undefined option name
    if (!optionName) {
      console.warn('Selected option has no name for current language:', option);
      return;
    }

    this.selectedOption.set(option);
    this.parentForm.get(this.controlName)?.setValue(optionName);
    this.optionSelected.emit(option);
    // this.searching.set(false);
  }

  loadMore(): void {
    this.pageSearch.update((current) => ({
      ...current,
      page: current.page + 1,
    }));

    this.viewMoreClicked.emit({
      ...this.pageSearch(),
    });
  }
}
