import { Component, EventEmitter, Input, Output } from '@angular/core';
import { FormGroup, ReactiveFormsModule } from '@angular/forms';
import { CustomAppErrorComponent } from '../custom-app-error/custom-app-error.component';
import { IComponentFormError } from '../../interfaces';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'custom-check-box-form',
  standalone: true,
  imports: [CustomAppErrorComponent, ReactiveFormsModule, CommonModule],
  templateUrl: './custom-check-box-form.component.html',
  styleUrls: ['./custom-check-box-form.component.scss'],
})
export class CustomCheckBoxFormComponent {
  @Input() checkboxClass: string = '';
  @Input() componentClass: string = '';
  @Input() labelClass: string = '';
  @Input() label: string = '';
  @Input({ required: true }) name: string = '';
  @Input({ required: true }) controlName: string = '';
  @Input({ required: true }) parentForm!: FormGroup;
  @Input({ required: true }) validation: IComponentFormError[] = [];
  @Input() disabled: boolean = false;

  @Output()
  valueChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  uniqueId: string = this.setUniqueId();

  setUniqueId(): string {
    return (
      this.name +
      '_' +
      this.controlName +
      '_' +
      Math.random().toString(36).substring(2, 15)
    );
  }

  ngOnChanges() {
    if (this.parentForm.controls[this.controlName].valueChanges) {
      this.parentForm.controls[this.controlName].valueChanges.subscribe(
        (val) => {
          this.valueChange.emit(val);
        },
      );
    }
  }
}
