import { NgStyle } from '@angular/common';
import {
  Component,
  EventEmitter,
  inject,
  input,
  Input,
  Output,
  SimpleChanges,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { ClickOutsideDirective } from '../../directives';
import { LocalizePipe } from '../../pipes';
import { IDropdownOption } from '../../interfaces';
import { TranslationService } from '../../services';

@Component({
  selector: 'custom-dropdown-with-add',
  imports: [
    NgStyle,
    FormsModule,
    ClickOutsideDirective,
    LocalizePipe,
    TranslateModule,
  ],
  templateUrl: './custom-dropdown-with-add.component.html',
  styleUrl: './custom-dropdown-with-add.component.css',
})
export class CustomDropdownWithAddComponent {
  @Input() label?: string;
  @Input() labelClass: string = '';
  @Input() dropdownOptionsClass: string = '';
  @Input() dropdownHeaderClass: string = '';
  @Input() selectedClass: string = '';
  @Input() dropdownContainerClass: string = '';
  @Input() placeholder: string = 'GENERAL.SELECT_OPTION';
  @Input() enableFilter: boolean = false;
  @Input() showClear: boolean = true;
  @Input() isRequired: boolean = false;
  @Input() vmsFlexDesignMood: boolean = false;
  @Input({ required: true }) options: IDropdownOption[] = [];
  @Input({ required: true }) name?: string;
  @Input({ required: true }) value: any;
  @Input() customId?: string;
  @Input() height: string = '4.8em';

  // New inputs for "Other" functionality
  @Input() enableOtherOption: boolean = false;
  @Input() otherOptionLabel: string = 'GENERAL.OTHER';
  @Input() otherInputPlaceholder: string = 'GENERAL.ENTER_VALUE';
  @Input() otherButtonText: string = 'GENERAL.ADD';

  otherValue = input<string>('');

  @Output() valueChange = new EventEmitter<{
    type: 'option' | 'other';
    value: IDropdownOption | string | null;
  }>();

  isOpen: boolean = false;
  filteredOptions: IDropdownOption[] = [];
  filterText: string = '';
  translationService = inject(TranslationService);

  // Properties for "Other" functionality
  otherCustomValue: string = '';
  selectedOtherValue: string = ''; // Store confirmed other value

  ngOnInit() {
    this.filteredOptions = [...this.options];
  }

  ngOnChanges(changes: SimpleChanges) {
    console.log('Changes detected in CustomDropdownWithAddComponent:', changes);
    if (changes['otherValue']) {
      if (this.otherValue()) {
        this.selectedOtherValue = this.otherValue();
      }
    }
  }

  get selectedOption(): IDropdownOption | null {
    return this.options.find((opt) => opt.id === this.value) || null;
  }

  get displayValue(): string {
    // If there's a confirmed "other" value, show it
    if (this.selectedOtherValue) {
      return this.selectedOtherValue;
    }
    // Otherwise show the selected option
    if (this.selectedOption) {
      return this.selectedOption.nameEn || this.selectedOption.nameAr;
    }
    return '';
  }

  toggleDropdown() {
    this.isOpen = !this.isOpen;
    if (this.isOpen) {
      this.filterText = '';
      this.filterOptions();
    }
  }

  selectOption(option: IDropdownOption) {
    // Clear other value when selecting a regular option
    this.selectedOtherValue = '';
    this.otherCustomValue = '';

    this.value = option.id;
    this.valueChange.emit({
      type: 'option',
      value: option,
    });
    this.isOpen = false;

    console.log('Regular option selected:', {
      type: 'option',
      value: option,
    });
  }

  clearSelection(event: Event) {
    event.stopPropagation();
    this.value = null;
    this.selectedOtherValue = '';
    this.otherCustomValue = '';
    this.valueChange.emit({
      type: 'option',
      value: null,
    });

    console.log('Selection cleared');
  }

  filterOptions() {
    if (!this.filterText) {
      this.filteredOptions = [...this.options];
    } else {
      const searchText = this.filterText.toLowerCase();
      this.filteredOptions = this.options.filter(
        (option) =>
          option.nameEn.toLowerCase().includes(searchText) ||
          option.nameAr.toLowerCase().includes(searchText),
      );
    }
  }

  confirmOtherValue(event: Event) {
    event.stopPropagation();
    if (this.otherCustomValue.trim()) {
      // Clear regular option selection
      this.value = null;

      // Store the confirmed other value
      this.selectedOtherValue = this.otherCustomValue.trim();

      this.valueChange.emit({
        type: 'other',
        value: this.selectedOtherValue,
      });

      console.log('Other value added:', {
        type: 'other',
        value: this.selectedOtherValue,
      });

      this.otherCustomValue = ''; // Clear input
      this.isOpen = false;
    }
  }

  @Input() set reset(value: boolean) {
    if (value) {
      this.value = null;
      this.filterText = '';
      this.selectedOtherValue = '';
      this.otherCustomValue = '';
      this.filterOptions();
    }
  }
}
