import { CommonModule } from '@angular/common';
import { Component, EventEmitter, Input, Output } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'custom-check-box',
  imports: [CommonModule, TranslateModule],
  templateUrl: './custom-check-box.component.html',
  styleUrl: './custom-check-box.component.css',
})
export class CustomCheckBoxComponent {
  @Input() checkboxClass: string = '';
  @Input() componentClass: string = '';
  @Input() labelClass: string = '';
  @Input() label: string = '';
  @Input({ required: true }) name: string = '';
  @Input() customId?: string;
  @Input() disabled: boolean = false;
  // Direct value binding instead of Form logic
  @Input() value: boolean = false;
  @Output() valueChange = new EventEmitter<boolean>();

  // Unique ID for the label "for" attribute
  uniqueId: string = `checkbox_${Math.random().toString(36).substring(2, 11)}`;

  toggleValue(event: Event) {
    const input = event.target as HTMLInputElement;
    this.value = input.checked;
    this.valueChange.emit(this.value);
  }
}
