import { NgStyle, NgTemplateOutlet } from '@angular/common';
import { Component, ContentChild, ElementRef, HostListener, Input, TemplateRef, inject } from '@angular/core';
@Component({
  selector: 'custom-tooltip',
  imports: [NgStyle, NgTemplateOutlet],
  templateUrl: './custom-tooltip.component.html',
  styleUrl: './custom-tooltip.component.css',
  host: {
    '(mouseenter)': 'show()',
    '(mouseleave)': 'hide()',
    '[class.tooltip-host]': 'true',
  },
})
export class CustomTooltipComponent {
  @Input() customClass: string = '';
  @Input() text: string = '';
  @Input() title: string = '';
  @Input() delay: number = 100;
  @Input() position: 'top' | 'bottom' | 'left' | 'right' | 'bottom-end' = 'top';
  @Input() template?: TemplateRef<any>;
  @Input() templateContext?: any;
  @Input() minWidth: string = '160px';

  visible = false;
  tooltipStyle: Record<string, string> = {};
  private timeoutId: any;
  private readonly el = inject(ElementRef);

  @HostListener('window:scroll')
  @HostListener('window:resize')
  onScrollOrResize(): void {
    if (this.visible) {
      this.calculatePosition();
    }
  }

  show() {
    this.timeoutId = setTimeout(() => {
      this.calculatePosition();
      this.visible = true;
    }, this.delay);
  }

  hide() {
    clearTimeout(this.timeoutId);
    this.visible = false;
  }

  private calculatePosition(): void {
    const rect: DOMRect = this.el.nativeElement.getBoundingClientRect();
    const margin = 8;
    const isRtl = document.documentElement.dir === 'rtl';
    const style: Record<string, string> = {};

    switch (this.position) {
      case 'top':
        style['bottom'] = `${window.innerHeight - rect.top + margin}px`;
        style['left'] = `${rect.left + rect.width / 2}px`;
        style['transform'] = 'translateX(-50%)';
        break;
      case 'bottom':
        style['top'] = `${rect.bottom + margin}px`;
        style['left'] = `${rect.left + rect.width / 2}px`;
        style['transform'] = 'translateX(-50%)';
        break;
      case 'bottom-end':
        style['top'] = `${rect.bottom}px`;
        if (isRtl) {
          style['right'] = `${window.innerWidth - rect.left}px`;
        } else {
          style['left'] = `${rect.right}px`;
        }
        break;
      case 'right':
        style['top'] = `${rect.top + rect.height / 2}px`;
        style['transform'] = 'translateY(-50%)';
        if (isRtl) {
          style['right'] = `${window.innerWidth - rect.left + margin}px`;
        } else {
          style['left'] = `${rect.right + margin}px`;
        }
        break;
      case 'left':
        style['top'] = `${rect.top + rect.height / 2}px`;
        style['transform'] = 'translateY(-50%)';
        if (isRtl) {
          style['left'] = `${rect.right + margin}px`;
        } else {
          style['right'] = `${window.innerWidth - rect.left + margin}px`;
        }
        break;
    }

    this.tooltipStyle = style;
  }
}
