import { isPlatformBrowser } from '@angular/common';
import { HttpErrorResponse, HttpInterceptorFn } from '@angular/common/http';
import { inject, PLATFORM_ID } from '@angular/core';
import {
  catchError,
  mergeMap,
  retry,
  retryWhen,
  throwError,
  timer,
} from 'rxjs';
import {
  AuthContextService,
  AuthService,
  StorageService,
  ToastService,
} from '../../services';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { AuthConstant } from '../../enums';

export const ErrorInterceptor: HttpInterceptorFn = (req, next) => {
  let authService = inject(AuthService);
  let authContextService = inject(AuthContextService);
  let router = inject(Router);
  let toastService = inject(ToastService);
  const storageService = inject(StorageService);
  const translateService = inject(TranslateService);
  return next(req).pipe(
    catchError((error: HttpErrorResponse) => {
      const lang = translateService.currentLang || 'en';
      const suffix = lang.charAt(0).toUpperCase() + lang.slice(1);
      const isRefreshRequest = req.url.includes('/api/v1/idm/auth/refresh');
      switch (error.status) {
        case 400:
        case 409:
          const errBody = error.error;
          const lang = translateService.currentLang || 'en';
          const isAr = lang.toLowerCase() === 'ar';
          // Invalid credentials come back as a 400 with a plain
          // "Authentication failed: ... invalid_grant ..." message.
          const backendMsg: string = errBody?.message || '';
          if (
            error.status === 400 &&
            (backendMsg.toLowerCase().includes('authentication failed') ||
              backendMsg.includes('invalid_grant'))
          ) {
            toastService.toast(
              translateService.instant('TOASTERS.AUTHENTICATION_FAILED'),
              'top-center',
              'error',
              2000,
              translateService.instant('TOASTERS.INVALID_CREDENTIALS'),
            );
            break;
          }
          const msg = isAr ? errBody?.errorMessageAr : errBody?.errorMessageEn;
          const finalMsg = msg || errBody?.errorMessage || 'Bad Request';
          toastService.toast(
            translateService.instant(finalMsg),
            'top-center',
            'error',
            2000,
            translateService.instant('TOASTERS.SOMETHING_WENT_WRONG_SUPPORT'),
          );
          break;

        case 401:
          // Do not recurse when refresh endpoint itself returns 401.
          if (isRefreshRequest) {
            authContextService.clearData();
            // Survives clearData() - read once by the login screen to explain
            // why the user was kicked out.
            storageService.addSessionItem(AuthConstant.SESSION_EXPIRED, 'true');
            window.dispatchEvent(new CustomEvent('auth-logout'));
            router.navigate(['/auth']);
            break;
          }
          // access token expired / au auth
          // if not guest-portal or zone-redirect, then refresh token
          if (!req.url.includes('/api/v1/guest-portal')) {
            authService.handleRefreshToken();
          }
          //  authContextService.clearData();
          // window.dispatchEvent(new CustomEvent('auth-logout'));
          // router.navigate(['/auth/login']);
          break;
        case 403:
          // no permission
          toastService.toast(
            translateService.instant('TOASTERS.NO_PERMISSION'),
            'top-center',
            'error',
            2000,
            translateService.instant('TOASTERS.CONTACT_ADMIN'),
          );
          authService.handlePermissionConfig();
          console.error('No Permission');
          break;

        case 406:
          // refresh expired
          authContextService.clearData();
          storageService.addSessionItem(AuthConstant.SESSION_EXPIRED, 'true');
          window.dispatchEvent(new CustomEvent('auth-logout'));
          router.navigate(['/auth']);
          break;
        case 404:
          console.error('End Point Not Found');
          break;
        case 503:
          toastService.toast(
            translateService.instant('TOASTERS.SERVICE_UNAVAILABLE'),
            'top-center',
            'error',
            2000,
            translateService.instant('TOASTERS.SERVICE_UNAVAILABLE_SUPPORT'),
          );
          break;
        default:
          toastService.toast(
            translateService.instant('TOASTERS.SOMETHING_WENT_WRONG'),
            'top-center',
            'error',
            2000,
            translateService.instant('TOASTERS.SOMETHING_WENT_WRONG_SUPPORT'),
          );
      }
      // refresh token + code
      // access token
      // 503 -- service idle -- error message
      // 404 -- end point not found // /

      // if (error.error && isPlatformBrowser(PLATFORM_ID)) {
      //   if (error.error.errors) {
      //     const errorTOASTERS = Object.values(error.error.errors).flat();
      //     errorTOASTERS.forEach((errorMessage: any) => {
      //       console.error(errorMessage);
      //     });
      //   } else if (error?.error?.message) {
      //     console.error(error.error.message);
      //   } else {
      //     console.error('Something went wrong');
      //   }
      // }
      return throwError(error);
    }),
  );
};
