import {
  Component,
  ContentChild,
  EventEmitter,
  inject,
  input,
  Input,
  Output,
  SimpleChanges,
  TemplateRef,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormGroup,
  FormsModule,
  ReactiveFormsModule,
} from '@angular/forms';
import { ClickOutsideDirective } from '../../directives';
import { CustomAppErrorComponent } from '../custom-app-error/custom-app-error.component';
import { IComponentFormError, IDropdownOption } from '../../interfaces';
import { ComponentFormErrorConstant } from '../../enums';
import { CommonModule, NgStyle, NgTemplateOutlet } from '@angular/common';
import { LocalizePipe } from '../../pipes';
import { TranslationService } from '../../services';
import { TranslateModule } from '@ngx-translate/core';
import { CustomSvgIconComponent } from '../custom-svg-icon/custom-svg-icon.component';

@Component({
  selector: 'custom-dropdown-form',
  standalone: true,
  imports: [
    NgStyle,
    FormsModule,
    ReactiveFormsModule,
    ClickOutsideDirective,
    CustomAppErrorComponent,
    LocalizePipe,
    TranslateModule,
    CommonModule,
    CustomSvgIconComponent,
    NgTemplateOutlet,
  ],
  templateUrl: './custom-dropdown-form.component.html',
  styleUrls: ['./custom-dropdown-form.component.css'],
})
export class CustomDropdownFormComponent {
  @Input({ required: true }) parentForm!: FormGroup | any;
  @Input({ required: true }) controlName!: string;
  @Input() label?: string;
  @Input() labelClass: string = '';
  @Input() dropdownOptionsClass: string = '';
  @Input() dropdownHeaderClass: string = '';
  @Input() dropdownContainerClass: string = '';
  @Input() placeholder: string = 'GENERAL.SELECT';
  @Input() enableFilter: boolean = false;
  @Input() showClear: boolean = true;
  @Input({ required: true }) options: IDropdownOption[] = [];
  @Input({ required: true }) name: string = '';
  @Input({ required: true }) validation: IComponentFormError[] = [];
  @Input() genericIcon: string = '';
  @Input() disabled: boolean = false;
  @Input() height: string = '4.8em';
  @Input() showInactive: boolean = true;
  @Input() emptyOption: string = 'GENERAL.NO_OPTIONS_FOUND';
  @Input() borderRadius: string = '0.5em';
  @Input() addOther: boolean = false;
  @Input() otherControlName: string = '';
  @Input() otherPlaceholder: string = 'GENERAL.OTHER';
  @Input() otherButtonText: string = 'GENERAL.ADD';
  @Output() valueChange: EventEmitter<IDropdownOption | null> =
    new EventEmitter<IDropdownOption | null>();
  @Output() otherSelected: EventEmitter<string> = new EventEmitter<string>();
  isOpen: boolean = false;
  @Output() toggledDropdown: EventEmitter<boolean> =
    new EventEmitter<boolean>();

  @ContentChild('optionTemplate') optionTemplate?: TemplateRef<any>;

  selectedOption: IDropdownOption | null = null;
  filteredOptions: IDropdownOption[] = [];
  filterText: string = '';
  public value: any;
  translationService = inject(TranslationService);
  ngOnInit() {
    this.filteredOptions = [...this.options];
    this.setupFormControlSubscription();
    // console.log('init form data', {
    //   controlName: this.controlName,
    //   formValue: this.parentForm.get(this.controlName)?.value,
    // });
  }

  ngOnChanges(changes: SimpleChanges) {
    // This will trigger when options are loaded from the parent
    if (changes['options'] && changes['options'].currentValue) {
      this.filteredOptions = [...this.options];
      this.updateSelectedOptionFromFormValue();

      if (this.selectedOption && this.selectedOption.disabled) {
        this.selectedOption = null;
        this.parentForm.get(this.controlName)?.setValue(null);
      }
    }
  }

  private setupFormControlSubscription() {
    if (this.parentForm && this.controlName) {
      const control = this.parentForm.get(this.controlName);
      if (control) {
        // Set initial value
        if (control.value) {
          this.value = control.value;
          this.updateSelectedOptionFromFormValue();
        }

        // Subscribe to future changes
        control.valueChanges.subscribe((value: any) => {
          this.value = value;
          this.updateSelectedOptionFromFormValue();
        });
      }
    }
  }

  private updateSelectedOptionFromFormValue() {
    const currentValue = this.parentForm.get(this.controlName)?.value;
    // console.log("Updating selected option:", {
    //   currentValue,
    //   options: this.options,
    //   controlName: this.controlName,
    // });

    if (currentValue && this.options.length > 0) {
      this.selectedOption =
        this.options.find((opt) => opt.id === currentValue) || null;
      // console.log("Found selected option:", this.selectedOption);
    } else {
      this.selectedOption = null;
    }
  }

  toggleDropdown() {
    this.isOpen = !this.isOpen;
    this.toggledDropdown.emit(this.isOpen);
    if (this.isOpen) {
      this.filterText = '';
      this.filterOptions();
    } else {
      this.parentForm.get(this.controlName)?.markAsTouched();
    }
    this.sortOptions();
  }

  sortOptions() {
    this.filteredOptions = [
      ...(this.selectedOption ? [this.selectedOption] : []),
      ...this.options.filter((option) => {
        return option.id !== this.selectedOption?.id;
      }),
    ];
  }

  closeDropdown() {
    this.isOpen = false;
    this.parentForm.get(this.controlName)?.markAsTouched();
  }

  writeValue(value: any): void {
    this.value = value;
  }

  selectOption(option: IDropdownOption) {
    // console.log("option", option);
    this.selectedOption = option;
    this.parentForm.get(this.controlName)?.setValue(option.id);
    this.isOpen = false;
    this.valueChange.emit(option);
    console.log('Emitted value:', option);
    this.toggledDropdown.emit(this.isOpen);
    this.parentForm.get(this.otherControlName)?.setValue('');
  }

  clearSelection(event: Event) {
    event.stopPropagation();
    this.selectedOption = null;
    this.parentForm.get(this.controlName)?.setValue(null);
    this.valueChange.emit(null);
    this.parentForm.get(this.otherControlName)?.setValue('');
  }

  filterOptions() {
    if (!this.filterText) {
      this.filteredOptions = [...this.options];
    } else {
      const searchText = this.filterText.toLowerCase();
      this.filteredOptions = this.options.filter(
        (option) =>
          option.nameEn.toLowerCase().includes(searchText) &&
          option.id !== 'other',
      );
    }
  }

  selectOther() {
    const otherTextValue = this.parentForm.get(this.otherControlName)?.value;
    if (otherTextValue && otherTextValue.trim()) {
      const otherOption: IDropdownOption = {
        id: 'other',
        nameEn: otherTextValue,
        nameAr: otherTextValue,
      } as IDropdownOption;
      if (!this.options.some((opt) => opt.id === 'other')) {
        this.options.push(otherOption);
      } else {
        const index = this.options.findIndex((opt) => opt.id === 'other');
        this.options[index] = otherOption;
      }
      this.selectedOption = otherOption;
      this.parentForm.get(this.controlName)?.setValue(otherOption.id);
      this.valueChange.emit(otherOption);
      this.otherSelected.emit(otherTextValue);
      setTimeout(() => {
        this.toggleDropdown();
      }, 1);
    }
  }

  @Input() set reset(value: boolean) {
    if (value) {
      this.selectedOption = null;
      this.filterText = '';
      if (this.otherControlName) {
        this.parentForm.get(this.otherControlName)?.setValue('');
      }
      this.filterOptions();
    }
  }

  containRequiredError() {
    return this.validation.some((error) =>
      error.errorType.includes(ComponentFormErrorConstant.REQUIRED),
    );
  }
}
